/* Contenido de la sustentación. Los textos, tablas y ejemplos proceden del PDF fuente. */
const S = [];
const add = (section, title, body, source = "") => S.push({ section, title, body, source });
const code = (s, cls = "") => `<pre class="${cls}"><code>${s.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;")}</code></pre>`;
const table = (heads, rows) => `<table><thead><tr>${heads.map(x=>`<th>${x}</th>`).join("")}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join("")}</tr>`).join("")}</tbody></table>`;
const cols = (...x) => `<div class="cols">${x.map(v=>`<div>${v}</div>`).join("")}</div>`;
const note = x => `<p class="lead">${x}</p>`;
const list = (...x) => `<ul>${x.map(v=>`<li>${v}</li>`).join("")}</ul>`;

add("Apertura", "PostgreSQL", `<div class="cover-logo"><img src="https://www.postgresql.org/media/img/about/press/elephant.png" alt="Logo de PostgreSQL"></div>`, "");
add("Apertura", "Agenda", `<div class="route"><div><b>01</b><span>PostgreSQL y modelo</span></div><div><b>02</b><span>SQL de consulta</span></div><div><b>03</b><span>Datos y transacciones</span></div><div><b>04</b><span>PL/pgSQL y cursores</span></div><div><b>05</b><span>Funciones y repaso</span></div></div>`, "");
add("PostgreSQL", "Qué hace un SGBD", cols(`<h3>Define</h3><p>Tablas, tipos y restricciones que describen los datos.</p>`, `<h3>Almacena</h3><p>Organiza la información en archivos y estructuras internas.</p>`, `<h3>Opera</h3><p>Inserta, consulta, modifica y elimina información.</p>`, `<h3>Protege</h3><p>Integridad, concurrencia, recuperación y permisos.</p>`)+note("Un sistema gestor de bases de datos administra el ciclo de vida de los datos de una organización."), "PDF p. 1");
add("PostgreSQL", "SQL se organiza por tareas", table(["Sublenguaje", "Para qué sirve", "Sentencias de la fuente"], [["DQL", "Leer datos", "SELECT"],["DML", "Cambiar datos", "INSERT · UPDATE · DELETE"],["DDL", "Definir estructuras", "CREATE · ALTER · DROP"],["DCL", "Controlar permisos", "GRANT · REVOKE"],["TCL", "Confirmar o deshacer", "COMMIT · ROLLBACK · SAVEPOINT"]]), "PDF p. 1");
add("PostgreSQL", "Propiedades que explican su comportamiento", `<div class="feature-rail"><div><b>ACID</b><span>Transacciones confiables</span></div><div><b>MVCC</b><span>Versiones consistentes</span></div><div><b>WAL</b><span>Registro para recuperación</span></div></div><div class="property-map" aria-label="Rasgos destacados de PostgreSQL"><div><b>Extensible</b><span>Tipos · funciones · operadores · extensiones</span></div><div><b>Datos</b><span>Arreglos · JSON/JSONB · rangos · UUID · fechas</span></div><div><b>Procedural</b><span>PL/pgSQL y otros lenguajes</span></div><div><b>Comunidad</b><span>Proyecto nacido de POSTGRES, en Berkeley</span></div></div>`, "PDF p. 1");
add("PostgreSQL", "Arquitectura básica: PostgreSQL frente a Oracle", `<div class="dual-architecture" aria-label="Comparación visual de arquitecturas PostgreSQL y Oracle"><div class="engine-diagram postgresql-diagram"><h3>PostgreSQL</h3><div class="diagram-flow"><div class="diagram-block clients-block">Clientes</div><span class="diagram-arrow">↓</span><div class="diagram-block connection-block">postmaster</div><span class="diagram-arrow">↓</span><div class="diagram-processes"><span>Backend 1</span><span>Backend 2</span><span>Backend 3</span></div><span class="diagram-arrow">↓</span><div class="diagram-block memory-block">Shared Buffers</div><span class="diagram-arrow">↓</span><div class="diagram-block persistence-block">WAL</div></div><div class="diagram-extra">Mantenimiento: <b>autovacuum</b></div></div><div class="engine-diagram oracle-diagram"><h3>Oracle</h3><div class="diagram-flow"><div class="diagram-block clients-block">Clientes</div><span class="diagram-arrow">↓</span><div class="diagram-block connection-block">Listener</div><span class="diagram-arrow">↓</span><div class="diagram-processes"><span>Servidor dedicado</span><span>Servidor compartido</span></div><span class="diagram-arrow">↓</span><div class="diagram-block memory-block">SGA + PGA</div><span class="diagram-arrow">↓</span><div class="diagram-block persistence-block">Redo Logs</div></div><div class="diagram-extra">Gestión de versiones: <b>UNDO</b></div></div></div><p class="architecture-disclaimer"><b>Autovacuum</b> y <b>UNDO</b> cumplen funciones distintas: no son mecanismos equivalentes.</p>`, "");
add("PostgreSQL", "Herramientas para explorar la base", table(["Comando", "Uso"], [["psql -U usuario -d basedatos","Conectarse"],["\\l · \\c nombre","Listar / cambiar base"],["\\dt · \\d tabla","Listar / describir tablas"],["\\df · \\q","Listar funciones / salir"]])+note("pgAdmin ofrece una interfaz gráfica; el documento lo compara con SQL Developer.")+`<div class="psql-map" aria-label="Secuencia de uso de psql"><div><b>1 · Conectar</b><span>psql -U usuario -d basedatos</span></div><i aria-hidden="true">→</i><div><b>2 · Explorar</b><span>\\l · \\dt · \\d tabla · \\df</span></div><i aria-hidden="true">→</i><div><b>3 · Elegir acción</b><span>Cambiar de base o salir con \\c / \\q</span></div></div>`, "PDF p. 2");
add("Modelo de ejemplo", "Un esquema, dos tablas", `<div class="entity-map"><div class="entity"><h3>departamentos</h3><p><b>id</b> INTEGER · PK</p><p>nombre VARCHAR(30) · NOT NULL</p><p>ciudad VARCHAR(30)</p></div><div class="relation">departamento_id → id</div><div class="entity"><h3>empleados</h3><p><b>id</b> INTEGER · PK</p><p>nombre, apellido · NOT NULL</p><p>salario, comision · NUMERIC(10,2)</p><p>fecha_ingreso · DATE</p><p>departamento_id → departamentos</p><p>jefe_id → empleados.id</p></div></div><p class="muted">La relación jefe-empleado es una referencia de la tabla a sí misma.</p><details><summary>Ver el CREATE TABLE completo</summary>${code("CREATE TABLE departamentos (\nid INTEGER PRIMARY KEY,\nnombre VARCHAR(30) NOT NULL,\nciudad VARCHAR(30)\n);\n\nCREATE TABLE empleados (\nid INTEGER PRIMARY KEY,\nnombre VARCHAR(30) NOT NULL,\napellido VARCHAR(30) NOT NULL,\nsalario NUMERIC(10,2),\ncomision NUMERIC(10,2),\nfecha_ingreso DATE,\ndepartamento_id INTEGER REFERENCES departamentos(id),\njefe_id INTEGER REFERENCES empleados(id)\n);")}</details>`, "PDF pp. 2–3");
add("Modelo de ejemplo", "Los datos que dan sentido a los JOIN", table(["Departamento", "Ciudad", "Empleados"], [["Ventas (10)","Tunja","Luis, Carlos"],["Sistemas (20)","Bogotá","Ana, María, Juan"],["Contabilidad (30)","Duitama","Sofía"],["Logística (40)","NULL","—"]])+`<p class="callout">Paula Vega no tiene departamento y Logística no tiene empleados. Así se ve qué filas conserva cada JOIN externo.</p><details><summary>Ver los INSERT de ejemplo</summary>${code("INSERT INTO departamentos VALUES\n(10, 'Ventas', 'Tunja'),\n(20, 'Sistemas', 'Bogotá'),\n(30, 'Contabilidad', 'Duitama'),\n(40, 'Logística', NULL);\n\nINSERT INTO empleados VALUES\n(1, 'Ana', 'Torres', 9000000, NULL, '2015-03-01', 20, NULL),\n(2, 'Luis', 'Pérez', 6500000, 500000, '2018-07-15', 10, 1),\n(3, 'María', 'Gómez', 5200000, NULL, '2020-01-10', 20, 1),\n(4, 'Carlos', 'Rojas', 4800000, 300000, '2019-11-23', 10, 2),\n(5, 'Sofía', 'Díaz', 3900000, NULL, '2022-05-02', 30, 1),\n(6, 'Juan', 'Mora', 4100000, NULL, '2021-09-30', 20, 3),\n(7, 'Paula', 'Vega', 3500000, NULL, '2023-02-14', NULL, 5);")}</details>`, "PDF p. 3");
add("Consultas SQL", "DQL: proyectar, seleccionar y asociar", `<div class="three-terms"><div><b>Proyección</b><span>Qué columnas: SELECT nombre, salario</span></div><div><b>Selección</b><span>Qué filas: WHERE salario &gt; 4000000</span></div><div><b>Asociación</b><span>Qué tablas: JOIN por columnas relacionadas</span></div></div>${note("Toda consulta del recorrido parte de estas tres decisiones.")}`, "PDF p. 3");
add("Consultas SQL", "SELECT y FROM forman la consulta", `<div class="tabs" data-tabs><div class="tab-buttons"><button>Consulta</button><button>Lectura</button><button>Dato verificable</button></div><div class="tab-panel">${code("SELECT * FROM empleados;\n\nSELECT nombre, salario AS sueldo FROM empleados;")}</div><div class="tab-panel"><p><code>*</code> pide todas las columnas. La segunda consulta proyecta solo nombre y salario; el alias <code>sueldo</code> cambia la etiqueta del resultado.</p></div><div class="tab-panel"><p>El esquema contiene siete empleados. La fuente no presenta una salida tabular completa para estas dos consultas.</p></div></div>`, "PDF p. 3");
add("Consultas SQL", "WHERE filtra filas antes de proyectar", `<div class="tabs" data-tabs><div class="tab-buttons"><button>Consulta</button><button>Lectura</button><button>Resultado citado</button></div><div class="tab-panel">${code("SELECT nombre, apellido\nFROM empleados\nWHERE salario > 4000000;")}</div><div class="tab-panel"><p>Se evalúa la condición para cada fila. Solo se devuelven las columnas de la lista SELECT.</p></div><div class="tab-panel"><p>Con los datos del documento califican Ana, Luis, María, Carlos y Juan. Sofía y Paula quedan por debajo del umbral.</p></div></div>`, "PDF p. 3");
add("Consultas SQL", "Orden lógico: FROM → WHERE → SELECT", `<div class="sequence"><span>1 · FROM<br><small>establece las filas</small></span><i>→</i><span>2 · WHERE<br><small>filtra las filas</small></span><i>→</i><span>3 · SELECT<br><small>elige columnas</small></span></div><p class="callout">Un alias creado en SELECT no está disponible en WHERE; sí puede usarse en ORDER BY.</p>`, "PDF p. 3");
add("Consultas SQL", "Operadores de comparación", table(["Operadores", "Significado"], [["=","Igual"],["<> · !=","Distinto; ambas formas son válidas"],["> · <", "Mayor · menor"],[">= · <=","Mayor o igual · menor o igual"]])+note("Comparar NULL con = no produce verdadero: produce desconocido. Para comprobarlo se usa IS NULL."), "PDF p. 4");
add("Consultas SQL", "Combinar condiciones con AND, OR y NOT", `<div class="tabs" data-tabs><div class="tab-buttons"><button>AND</button><button>OR</button><button>NOT</button></div><div class="tab-panel">${code("WHERE departamento_id = 20 AND salario > 5000000")}</div><div class="tab-panel">${code("WHERE departamento_id = 10 OR departamento_id = 30")}</div><div class="tab-panel">${code("WHERE NOT departamento_id = 20")}</div></div><p class="muted">AND exige ambas condiciones. OR acepta alguna. NOT invierte una condición; con NULL, la lógica sigue siendo desconocida.</p>"`, "PDF p. 4");
add("Consultas SQL", "BETWEEN, IN y LIKE", cols(`<h3>Rango</h3>${code("salario BETWEEN 4000000 AND 6000000")}<p>BETWEEN incluye ambos extremos.</p>`, `<h3>Conjunto</h3>${code("departamento_id IN (10, 30)")}<p>Coincide con alguno de los valores listados.</p>`, `<h3>Patrón</h3>${code("nombre LIKE 'M%'\nnombre LIKE '_uis'")}<p>%: cualquier cantidad. _: un carácter.</p>`)+`<p class="muted">LIKE distingue mayúsculas y minúsculas; PostgreSQL ofrece ILIKE para ignorarlas.</p>`, "PDF pp. 4–5");
add("Consultas SQL", "NULL se propaga en operaciones aritméticas", `<div class="tabs" data-tabs><div class="tab-buttons"><button>Consulta</button><button>Lectura</button><button>Implicación</button></div><div class="tab-panel">${code("SELECT nombre, salario + comision AS total\nFROM empleados;\n\nSELECT 5 + NULL; -- NULL\nSELECT 7 / 2;    -- 3\nSELECT 7 / 2.0;  -- 3.5000000000000000")}</div><div class="tab-panel"><p>Si la comisión de una fila es NULL, la suma también lo es. La división entre enteros trunca la parte decimal.</p></div><div class="tab-panel"><p>Para obtener decimales, usa un operando decimal o un cast: <code>7::numeric / 2</code>.</p></div></div>`, "PDF pp. 3–4");
add("Consultas SQL", "Concatenar texto: || y CONCAT", `<div class="tabs" data-tabs><div class="tab-buttons"><button>Operador ||</button><button>Función CONCAT</button><button>CONCAT_WS</button></div><div class="tab-panel">${code("SELECT nombre || ' ' || apellido AS completo\nFROM empleados;\n\nSELECT 'Hola ' || NULL; -- NULL")}</div><div class="tab-panel">${code("SELECT CONCAT(nombre, ' ', apellido) AS completo\nFROM empleados;\n\nSELECT CONCAT('Hola ', NULL); -- Hola")}</div><div class="tab-panel"><p><code>CONCAT_WS(separador, a, b, ...)</code> concatena usando el separador. PostgreSQL acepta varios argumentos en CONCAT.</p></div></div><p class="muted">La diferencia clave de la fuente: || propaga NULL; CONCAT lo trata como cadena vacía.</p>"`, "PDF p. 4");
add("Consultas SQL", "La lógica de tres valores explica NULL", `<div class="logic-3"><div><b>TRUE</b><span>La condición coincide</span></div><div><b>FALSE</b><span>La condición no coincide</span></div><div><b>UNKNOWN</b><span>Falta un valor conocido</span></div></div>${code("WHERE comision IS NULL\nWHERE comision IS NOT NULL\n\n-- NOT IN con NULL puede dejar cero filas\n-- La fuente recomienda NOT EXISTS en subconsultas")}`, "PDF pp. 4–5");
add("Consultas SQL", "Precedencia: AND se evalúa antes que OR", `<div class="tabs" data-tabs><div class="tab-buttons"><button>Sin paréntesis</button><button>Con paréntesis</button><button>Regla</button></div><div class="tab-panel">${code("departamento_id = 10 OR\ndepartamento_id = 20 AND salario > 5000000")}</div><div class="tab-panel">${code("(departamento_id = 10 OR\ndepartamento_id = 20) AND salario > 5000000")}</div><div class="tab-panel"><p>La primera condición se interpreta como <code>dep 10 OR (dep 20 AND salario ...)</code>. Usa paréntesis para hacer explícito el alcance.</p></div></div><p class="muted">En orden descendente: aritmética, concatenación, comparaciones, IS NULL, NOT, AND, OR.</p>"`, "PDF p. 5");
add("Funciones SQL", "Funciones de una fila y de agrupamiento", `<div class="function-contrast"><div><b>Una fila</b><span>Recibe valores de una fila y devuelve un valor por cada fila.</span><em>LOWER · ROUND · TO_CHAR</em></div><div><b>Agregación</b><span>Recibe muchas filas y devuelve un resumen.</span><em>COUNT · AVG · SUM</em></div></div><p class="callout">Oracle usa DUAL para probar funciones. PostgreSQL permite <code>SELECT SQRT(16);</code> sin FROM.</p>`, "PDF pp. 5–6");
add("Funciones SQL", "Funciones numéricas", table(["Familia", "Funciones / ejemplo de la fuente"], [["Residuo y potencia","MOD(10,3)=1 · POWER(2,5)=32"],["Raíz y signo","SQRT(81)=9 · SIGN(-8)=-1 · ABS(-7.5)=7.5"],["Logaritmos","EXP(1) · LN(2.718...)≈1 · LOG(1000)=3"],["Trigonometría","SIN(PI()/2)=1 · argumentos en radianes"],["Decimales","TRUNC(15.789,1)=15.7 · ROUND(...)=15.8"]])+`<p class="muted">ROUND(x,n) con dos argumentos requiere NUMERIC; el documento muestra <code>x::numeric</code> para convertir double precision.</p>`, "PDF pp. 6–7");
add("Funciones SQL", "Funciones de cadenas", table(["Propósito", "Funciones del documento"], [["Cambiar caja","LOWER · UPPER · INITCAP"],["Recortar","TRIM · LTRIM · RTRIM"],["Extraer y medir","SUBSTR · LENGTH"],["Reemplazar","REPLACE · TRANSLATE"],["Completar / invertir","LPAD · RPAD · REVERSE"],["Códigos","ASCII · CHR"]]), "PDF pp. 6–7");
add("Funciones SQL", "Búsqueda de texto y SOUNDEX", `<div class="tabs" data-tabs><div class="tab-buttons"><button>Buscar subcadena</button><button>Comparar sonido</button><button>Aplicar a empleados</button></div><div class="tab-panel">${code("SELECT POSITION('SQL' IN 'PostgreSQL'); -- 8\nSELECT STRPOS('PostgreSQL', 'SQL');      -- 8")}</div><div class="tab-panel">${code("CREATE EXTENSION IF NOT EXISTS fuzzystrmatch;\nSELECT SOUNDEX('Robert'), SOUNDEX('Rupert'); -- R163, R163")}</div><div class="tab-panel">${code("SELECT nombre FROM empleados\nWHERE SOUNDEX(nombre) = SOUNDEX('Carlos');")}</div></div><p class="muted">PostgreSQL no tiene INSTR. La extensión fuzzystrmatch debe activarse por base de datos para SOUNDEX.</p>"`, "PDF p. 7");
add("Funciones SQL", "Agregados: resumen de varias filas", table(["Función", "Qué cuenta o calcula"], [["COUNT(*)","Todas las filas"],["COUNT(columna)","Valores no NULL"],["SUM · AVG","Suma · promedio"],["MAX · MIN","Máximo · mínimo"]])+`<div class="code-wide">${code("SELECT COUNT(*) AS total_filas, COUNT(comision) AS con_comision,\n       SUM(salario) AS nomina, ROUND(AVG(salario), 0) AS promedio,\n       MAX(salario) AS mayor, MIN(salario) AS menor\nFROM empleados;")}</div><p class="muted">La documentación indica 7 filas y 2 comisiones no nulas. Todos los agregados ignoran NULL, excepto COUNT(*).</p>`, "PDF p. 8");
add("Funciones SQL", "Sustituir y clasificar valores nulos", table(["Oracle", "PostgreSQL", "Idea"], [["NVL(a,b)","COALESCE(a,b)","Usar b cuando a es NULL"],["NVL2(a,x,y)","CASE WHEN a IS NOT NULL ...","Elegir según nulidad"],["COALESCE(a,b,c)","COALESCE(a,b,c)","Primer valor no nulo"],["NULLIF(a,b)","NULLIF(a,b)","NULL si a=b"]])+code("SELECT nombre, salario + COALESCE(comision, 0) AS total\nFROM empleados;"), "PDF p. 8");
add("Fechas", "Fechas: equivalencias de Oracle", table(["Oracle", "PostgreSQL según el documento"], [["SYSDATE","CURRENT_DATE o NOW()"],["SYSTIMESTAMP","CURRENT_TIMESTAMP"],["ADD_MONTHS(f,n)","f + INTERVAL 'n months'"],["MONTHS_BETWEEN(f1,f2)","AGE(f1,f2) + EXTRACT"],["NEXT_DAY · LAST_DAY","Cálculo con EXTRACT · date_trunc"],["EXTRACT(parte FROM f)","EXTRACT(parte FROM f)"]]), "PDF p. 9");
add("Fechas", "Sumar intervalos y restar fechas", `<div class="tabs" data-tabs><div class="tab-buttons"><button>Fecha actual</button><button>Sumar meses</button><button>Días transcurridos</button></div><div class="tab-panel">${code("SELECT CURRENT_DATE;\nSELECT CURRENT_TIMESTAMP;")}</div><div class="tab-panel">${code("SELECT CURRENT_DATE + INTERVAL '3 months';\nSELECT fecha_ingreso + INTERVAL '6 months'\nFROM empleados;")}</div><div class="tab-panel">${code("SELECT nombre, CURRENT_DATE - fecha_ingreso AS dias_en_empresa\nFROM empleados;")}</div></div><p class="callout">DATE en PostgreSQL guarda solo fecha; restar dos DATE produce días enteros.</p>"`, "PDF p. 9");
add("Fechas", "Meses completos y último día del mes", `<div class="cols"><div><h3>Meses completos transcurridos</h3>${code("EXTRACT(YEAR FROM AGE(CURRENT_DATE, fecha_ingreso)) * 12\n+ EXTRACT(MONTH FROM AGE(CURRENT_DATE, fecha_ingreso))")}</div><div><h3>Último día del mes</h3>${code("(date_trunc('month', DATE '2026-02-10')\n + INTERVAL '1 month - 1 day')::date\n-- 2026-02-28")}</div></div><p class="muted">La traducción depende de cuál parte de la diferencia se quiera expresar: días o meses completos.</p>"`, "PDF p. 9");
add("Fechas", "EXTRACT y relojes de PostgreSQL", `<div class="cols"><div>${code("EXTRACT(YEAR FROM fecha_ingreso)\nEXTRACT(MONTH FROM fecha_ingreso)\nEXTRACT(DAY FROM fecha_ingreso)")}</div><div><p>Partes mencionadas: DOW, ISODOW, QUARTER, WEEK, HOUR, MINUTE, SECOND y EPOCH.</p><p><code>NOW()</code> y <code>CURRENT_TIMESTAMP</code> expresan el inicio de la transacción. <code>clock_timestamp()</code> devuelve la hora real en cada llamada.</p></div></div><p class="callout">El ejemplo de NEXT_DAY usa ISODOW, donde lunes=1 y domingo=7.</p>"`, "PDF pp. 9–10");
add("Conversiones", "TO_CHAR presenta una fecha como texto", `<div class="tabs" data-tabs><div class="tab-buttons"><button>Fecha</button><button>Fecha y hora</button><button>Idioma / literal</button></div><div class="tab-panel">${code("SELECT TO_CHAR(CURRENT_DATE, 'DD/MM/YYYY');\n-- ejemplo de la fuente: 14/11/2026")}</div><div class="tab-panel">${code("SELECT TO_CHAR(CURRENT_TIMESTAMP,\n  'YYYY-MM-DD HH24:MI:SS');")}</div><div class="tab-panel">${code("SELECT nombre, TO_CHAR(fecha_ingreso,\n  'DD \"de\" TMMonth \"de\" YYYY')\nFROM empleados;")}</div></div>"`, "PDF p. 10");
add("Conversiones", "Máscaras de fecha: cada símbolo tiene un papel", table(["Máscara", "Salida o significado"], [["YYYY · YY","Año de 4 · 2 dígitos"],["MM · MONTH · Month · MON","Mes numérico o textual"],["DD · DDD","Día del mes · día del año"],["DAY · Day · DY · D","Día textual / número de semana"],["Q · WW","Trimestre · semana del año"],["HH24 · HH12 · MI · SS","Hora · minuto · segundo"],["AM · PM","Indicador de meridiano"]])+`<p class="muted">MONTH y DAY se rellenan a 9 caracteres. FM quita relleno; TM usa idioma lc_time. El texto literal va entre comillas dobles.</p>`, "PDF pp. 10–11");
add("Conversiones", "TO_CHAR con números", `<div class="tabs" data-tabs><div class="tab-buttons"><button>Miles y decimales</button><button>Ceros de relleno</button><button>Salarios</button></div><div class="tab-panel">${code("SELECT TO_CHAR(1234567.891, '9,999,999.99');\n-- 1,234,567.89")}</div><div class="tab-panel">${code("SELECT TO_CHAR(45, '0000'); -- 0045")}</div><div class="tab-panel">${code("SELECT TO_CHAR(salario, 'FM999,999,999')\nFROM empleados;")}</div></div>${table(["Máscara", "Función"], [["9 · 0","Dígito sin / con cero de relleno"],[". · ,","Decimal · miles"],["FM · L","Quita espacios · moneda local"]])}`, "PDF p. 12");
add("Conversiones", "Convertir entre tipos", table(["Función / forma", "Uso según la fuente"], [["TO_DATE(texto, formato)","Texto a fecha"],["TO_NUMBER(texto, formato)","Texto a número"],["TO_TIMESTAMP(texto, formato)","Texto a fecha y hora"],["::","Conversión directa en PostgreSQL"],["CAST(x AS tipo)","Forma estándar SQL"]])+code("SELECT TO_DATE('14/11/2026', 'DD/MM/YYYY') + 30;\nSELECT TO_NUMBER('1,234.50', '9,999.99') * 2;\nSELECT CAST('2026-11-14' AS date), '42'::integer + 1;"), "PDF p. 12");
add("Relaciones y consultas avanzadas", "Enlazar en WHERE: una condición indispensable", `<div class="tabs" data-tabs><div class="tab-buttons"><button>Consulta enlazada</button><button>Sin enlace</button><button>Comparación Oracle</button></div><div class="tab-panel">${code("SELECT e.nombre, e.apellido, d.nombre AS departamento\nFROM empleados e, departamentos d\nWHERE e.departamento_id = d.id;")}</div><div class="tab-panel"><p>Sin condición de enlace se obtiene producto cartesiano: cada fila de una tabla combinada con todas las de la otra.</p></div><div class="tab-panel"><p>Oracle admitía <code>(+)</code> para uniones externas. PostgreSQL usa LEFT, RIGHT o FULL JOIN.</p></div></div>`, "PDF p. 12");
add("Relaciones y consultas avanzadas", "INNER JOIN expresa la relación en ON", `<div class="tabs" data-tabs><div class="tab-buttons"><button>Consulta</button><button>Lectura</button><button>Atajo</button></div><div class="tab-panel">${code("SELECT e.nombre, d.nombre AS departamento\nFROM empleados e\nINNER JOIN departamentos d\n  ON e.departamento_id = d.id;")}</div><div class="tab-panel"><p>Solo conserva las filas cuyo departamento_id coincide con departamentos.id.</p></div><div class="tab-panel">${code("-- INNER JOIN y JOIN son equivalentes\n-- USING (columna) si el nombre coincide\n-- SELECT * FROM pedidos\n-- JOIN clientes USING (cliente_id);")}</div></div><p class="muted">ON define la relación; los filtros de negocio siguen en WHERE.</p>"`, "PDF p. 13");
add("Relaciones y consultas avanzadas", "Explora qué lado conserva cada JOIN", `<div class="join-lab" data-join-lab><div class="join-controls"><button data-kind="inner">INNER</button><button data-kind="left">LEFT</button><button data-kind="right">RIGHT</button><button data-kind="full">FULL</button><button data-kind="cross">CROSS</button></div><div class="venn"><div class="venn-a">empleados</div><div class="venn-b">departamentos</div><div class="venn-intersection">coincidencia</div></div><p class="join-description" aria-live="polite">INNER: conserva coincidencias. En este esquema son 6 filas.</p></div>${table(["Tipo", "Filas del ejemplo"], [["INNER","6 · sin Paula ni Logística"],["LEFT","7 · incluye a Paula"],["RIGHT","7 · incluye Logística"],["FULL","8 · Paula y Logística"],["CROSS","28 · 7 × 4"]])}`, "PDF p. 13");
add("Relaciones y consultas avanzadas", "JOIN externos conservan filas sin pareja", `<div class="cols"><div><h3>LEFT</h3>${code("SELECT e.nombre, d.nombre AS departamento\nFROM empleados e\nLEFT JOIN departamentos d\n  ON e.departamento_id = d.id;")}<p>Conserva los siete empleados.</p></div><div><h3>RIGHT</h3>${code("SELECT e.nombre, d.nombre AS departamento\nFROM empleados e\nRIGHT JOIN departamentos d\n  ON e.departamento_id = d.id;")}<p>Conserva los cuatro departamentos.</p></div></div><div class="code-wide"><h3>FULL OUTER JOIN</h3>${code("SELECT e.nombre, d.nombre AS departamento\nFROM empleados e\nFULL OUTER JOIN departamentos d\n  ON e.departamento_id = d.id;")}</div>`, "PDF p. 13");
add("Relaciones y consultas avanzadas", "Aislar las filas que no tienen pareja", `<div class="tabs" data-tabs><div class="tab-buttons"><button>Solo empleados</button><button>Solo departamentos</button><button>Solo no coincidentes</button></div><div class="tab-panel">${code("SELECT e.nombre\nFROM empleados e LEFT JOIN departamentos d\n  ON e.departamento_id = d.id\nWHERE d.id IS NULL; -- Paula")}</div><div class="tab-panel">${code("SELECT d.nombre\nFROM empleados e RIGHT JOIN departamentos d\n  ON e.departamento_id = d.id\nWHERE e.id IS NULL; -- Logística")}</div><div class="tab-panel">${code("SELECT e.nombre, d.nombre\nFROM empleados e FULL JOIN departamentos d\n  ON e.departamento_id = d.id\nWHERE e.id IS NULL OR d.id IS NULL;")}</div></div>`, "PDF pp. 13–14");
add("Relaciones y consultas avanzadas", "GROUP BY crea grupos de filas", `<div class="tabs" data-tabs><div class="tab-buttons"><button>Consulta</button><button>Leer el resultado</button><button>Regla</button></div><div class="tab-panel">${code("SELECT d.nombre, COUNT(*) AS empleados,\n       ROUND(AVG(e.salario), 0) AS promedio\nFROM empleados e JOIN departamentos d\n  ON e.departamento_id = d.id\nGROUP BY d.nombre\nORDER BY promedio DESC;")}</div><div class="tab-panel"><p>Se reúne una fila por cada departamento con coincidencias. Para cada grupo se calcula la cantidad y el promedio salarial.</p></div><div class="tab-panel"><p>Toda columna del SELECT fuera de un agregado debe aparecer en GROUP BY.</p></div></div>`, "PDF p. 14");
add("Relaciones y consultas avanzadas", "WHERE filtra filas; HAVING filtra grupos", `<div class="sequence"><span>FROM</span><i>→</i><span>WHERE<br><small>filas</small></span><i>→</i><span>GROUP BY</span><i>→</i><span>HAVING<br><small>grupos</small></span><i>→</i><span>SELECT</span></div>${code("SELECT departamento_id, COUNT(*)\nFROM empleados\nGROUP BY departamento_id\nHAVING COUNT(*) > 1;\n-- departamentos 10 y 20")}`, "PDF p. 14");
add("Relaciones y consultas avanzadas", "Subconsulta escalar: comparar contra un valor", `<div class="tabs" data-tabs><div class="tab-buttons"><button>Promedio general</button><button>Máximo salario</button><button>Idea clave</button></div><div class="tab-panel">${code("SELECT nombre, salario FROM empleados\nWHERE salario > (SELECT AVG(salario) FROM empleados);\n-- Ana y Luis")}</div><div class="tab-panel">${code("SELECT nombre FROM empleados\nWHERE salario = (SELECT MAX(salario) FROM empleados);")}</div><div class="tab-panel"><p>La subconsulta escalar entrega un solo valor para que la consulta externa lo use como umbral.</p></div></div>`, "PDF p. 14");
add("Relaciones y consultas avanzadas", "Correlacionadas y EXISTS", `<div class="tabs" data-tabs><div class="tab-buttons"><button>Promedio por departamento</button><button>EXISTS</button><button>Correlación</button></div><div class="tab-panel">${code("SELECT e.nombre, e.salario\nFROM empleados e\nWHERE e.salario > (SELECT AVG(e2.salario)\n  FROM empleados e2\n  WHERE e2.departamento_id = e.departamento_id);\n-- Ana y Luis")}</div><div class="tab-panel">${code("SELECT d.nombre FROM departamentos d\nWHERE EXISTS (SELECT 1 FROM empleados e\n  WHERE e.departamento_id = d.id);")}</div><div class="tab-panel"><p>La subconsulta usa una columna de la consulta exterior y se evalúa por cada fila externa.</p></div></div>`, "PDF pp. 14–15");
add("Relaciones y consultas avanzadas", "MINUS en Oracle se escribe EXCEPT", `<div class="comparison"><div><b>Oracle</b>${code("SELECT id FROM departamentos\nMINUS\nSELECT departamento_id FROM empleados;")}</div><div><b>PostgreSQL</b>${code("SELECT id FROM departamentos\nEXCEPT\nSELECT departamento_id FROM empleados;\n-- 40")}</div></div><p>Ambas consultas deben devolver el mismo número de columnas con tipos compatibles. EXCEPT elimina duplicados.</p><p class="muted">Operadores relacionados: UNION, UNION ALL e INTERSECT.</p>`, "PDF p. 15");
add("Relaciones y consultas avanzadas", "Self-join: un empleado se enlaza con su jefe", `<div class="tabs" data-tabs><div class="tab-buttons"><button>Consulta</button><button>¿Por qué LEFT?</button><button>CASE</button></div><div class="tab-panel">${code("SELECT e.nombre AS empleado, j.nombre AS jefe\nFROM empleados e\nLEFT JOIN empleados j ON e.jefe_id = j.id;")}</div><div class="tab-panel"><p>Ana no tiene jefe. LEFT JOIN la conserva y muestra NULL en la columna jefe.</p></div><div class="tab-panel">${code("CASE WHEN salario >= 6000000 THEN 'Alto'\n     WHEN salario >= 4000000 THEN 'Medio'\n     ELSE 'Bajo' END")}</div></div><p class="muted">CASE reemplaza DECODE; la fuente muestra variantes por condición y por igualdad.</p>`, "PDF p. 15");
add("Relaciones y consultas avanzadas", "ORDER BY y DISTINCT controlan la salida", `<div class="cols"><div>${code("ORDER BY departamento_id ASC, salario DESC\nORDER BY comision DESC NULLS LAST\nORDER BY 2 DESC")}</div><div>${code("SELECT DISTINCT departamento_id FROM empleados;\nSELECT COUNT(DISTINCT departamento_id)\nFROM empleados; -- 3")}</div></div><p>ASC es el valor por defecto. PostgreSQL coloca NULL al final en ASC y al inicio en DESC; NULLS FIRST/LAST cambia el orden.</p><p class="muted">DISTINCT ON (departamento_id) es una extensión PostgreSQL para elegir una fila por grupo si se acompaña de ORDER BY.</p>"`, "PDF p. 16");
add("Relaciones y consultas avanzadas", "Recorrer jerarquías con WITH RECURSIVE", `<div class="tabs" data-tabs><div class="tab-buttons"><button>Raíz</button><button>Recursión</button><button>Secuencia</button></div><div class="tab-panel">${code("SELECT id, nombre, jefe_id, 1 AS nivel\nFROM empleados WHERE jefe_id IS NULL")}</div><div class="tab-panel">${code("SELECT e.id, e.nombre, e.jefe_id, j.nivel + 1\nFROM empleados e JOIN jerarquia j\n  ON e.jefe_id = j.id")}</div><div class="tab-panel">${code("SELECT generate_series(1, 5) AS nivel;")}</div></div><p class="muted">WITH RECURSIVE reemplaza CONNECT BY para jerarquías. generate_series reemplaza la secuencia basada en CONNECT BY LEVEL.</p>`, "PDF p. 16");
add("Definición y cambios", "CREATE TABLE declara estructura y reglas", `<div class="tabs" data-tabs><div class="tab-buttons"><button>Tabla clientes del PDF</button><button>Esquema de trabajo</button><button>Lectura</button></div><div class="tab-panel">${code("CREATE TABLE clientes (\n  id INTEGER PRIMARY KEY,\n  cedula VARCHAR(15) UNIQUE NOT NULL,\n  nombre VARCHAR(50) NOT NULL,\n  correo VARCHAR(80) UNIQUE,\n  saldo NUMERIC(12,2) DEFAULT 0 CHECK (saldo >= 0),\n  registro DATE DEFAULT CURRENT_DATE\n);")}</div><div class="tab-panel">${code("CREATE TABLE departamentos (\n  id INTEGER PRIMARY KEY,\n  nombre VARCHAR(30) NOT NULL,\n  ciudad VARCHAR(30)\n);\n\nCREATE TABLE empleados (...);")}</div><div class="tab-panel"><p>Columnas, tipos y restricciones se declaran en la misma estructura.</p></div></div>`, "PDF pp. 2, 17");
add("Definición y cambios", "Tipos de dato: nombres parecidos, diferencias útiles", table(["Oracle", "PostgreSQL"], [["NUMBER(p,s)","NUMERIC(p,s)"],["NUMBER entero","INTEGER · BIGINT · SMALLINT"],["VARCHAR2(n)","VARCHAR(n) o TEXT"],["CHAR(n)","CHAR(n)"],["DATE con fecha y hora","DATE solo fecha · TIMESTAMP con hora"],["BINARY_INTEGER","INTEGER"],["BOOLEAN (versiones previas a 23ai en PL/SQL)","BOOLEAN"]]), "PDF p. 17");
add("Definición y cambios", "Restricciones: qué protegen", table(["Restricción", "Garantía indicada en la fuente"], [["PRIMARY KEY","Fila única, no NULL; una por tabla"],["UNIQUE","Evita repetidos; admite NULL y varias columnas/reglas"],["NOT NULL","La columna debe tener valor"],["CHECK(condición)","El valor cumple una condición"],["DEFAULT valor","Valor usado si se omite la columna"],["REFERENCES","El valor existe en la tabla padre"]]), "PDF p. 17");
add("Definición y cambios", "Claves compuestas e identidad", `<div class="cols"><div><h3>Clave compuesta</h3>${code("CREATE TABLE inscripciones (\n  estudiante_id INTEGER,\n  curso_id INTEGER,\n  fecha DATE DEFAULT CURRENT_DATE,\n  CONSTRAINT pk_inscripciones\n    PRIMARY KEY (estudiante_id, curso_id),\n  CONSTRAINT uq_ejemplo UNIQUE (curso_id, fecha)\n);")}</div><div><h3>Identidad autoincremental</h3>${code("CREATE TABLE productos (\n  id INTEGER GENERATED ALWAYS AS IDENTITY\n    PRIMARY KEY,\n  nombre VARCHAR(40) NOT NULL\n);")}</div></div>`, "PDF pp. 17–18");
add("Definición y cambios", "INSERT agrega una o varias filas", `<div class="tabs" data-tabs><div class="tab-buttons"><button>Columnas explícitas</button><button>Varias filas</button><button>Desde SELECT</button><button>RETURNING</button></div><div class="tab-panel">${code("INSERT INTO clientes (id, cedula, nombre, correo)\nVALUES (1, '1052000111', 'Laura Ríos', 'laura@correo.com');")}</div><div class="tab-panel">${code("INSERT INTO clientes (id, cedula, nombre) VALUES\n  (2, '1052000222', 'Pedro Silva'),\n  (3, '1052000333', 'Elena Cruz');")}</div><div class="tab-panel">${code("INSERT INTO clientes (id, cedula, nombre)\nSELECT id + 100, '9' || id, nombre FROM empleados;")}</div><div class="tab-panel">${code("INSERT INTO productos (nombre)\nVALUES ('Té') RETURNING id;")}</div></div><p class="muted">La fuente recomienda indicar columnas. Si se omite una, se usa DEFAULT o NULL; una clave repetida genera error.</p>"`, "PDF p. 18");
add("Definición y cambios", "UPDATE y DELETE necesitan un filtro deliberado", `<div class="comparison"><div><h3>Modificar</h3>${code("UPDATE empleados\nSET salario = salario * 1.05\nWHERE departamento_id = 20;")}</div><div><h3>Eliminar</h3>${code("DELETE FROM clientes WHERE id = 3;")}</div></div><p class="callout">Sin WHERE, UPDATE y DELETE afectan todas las filas.</p>`, "PDF p. 18");
add("Definición y cambios", "Transacciones y cambios de estructura", `<div class="cols"><div><h3>Unidad transaccional</h3>${code("BEGIN;\nUPDATE clientes\nSET saldo = saldo - 100\nWHERE id = 1;\nCOMMIT;\n-- o ROLLBACK")}</div><div><h3>Estructura</h3>${code("ALTER TABLE clientes\n  ADD COLUMN telefono VARCHAR(15);\n\nDROP TABLE inscripciones;\nDROP TABLE clientes CASCADE;")}</div></div><p>La fuente indica autocommit para sentencias sueltas en PostgreSQL y COMMIT explícito en Oracle.</p>"`, "PDF p. 18");
add("PL/pgSQL", "Un bloque anónimo corre dentro del servidor", `<div class="tabs" data-tabs><div class="tab-buttons"><button>Bloque</button><button>Partes</button><button>Oracle</button></div><div class="tab-panel">${code("DO $$\nBEGIN\n  RAISE NOTICE 'Hola desde PL/pgSQL';\nEND $$;")}</div><div class="tab-panel"><p>DECLARE contiene variables y es opcional. BEGIN ... END agrupa instrucciones. EXCEPTION es una sección opcional al final.</p></div><div class="tab-panel"><p>Oracle escribe el bloque sin DO ni $$ y lo cierra con una barra / en la línea siguiente.</p></div></div>`, "PDF p. 19");
add("PL/pgSQL", "Declarar variables y constantes", `<div class="tabs" data-tabs><div class="tab-buttons"><button>Declaración</button><button>Asignación</button><button>Salida</button></div><div class="tab-panel">${code("DO $$\nDECLARE\n  v_edad INTEGER := 25;\n  v_nombre VARCHAR(30) DEFAULT 'Daniel';\n  v_activo BOOLEAN := TRUE;\n  v_hoy DATE := CURRENT_DATE;\n  c_iva CONSTANT NUMERIC := 0.19;\n  v_total NUMERIC;\nBEGIN ... END $$;")}</div><div class="tab-panel">${code("v_total := 100000 * (1 + c_iva);")}</div><div class="tab-panel">${code("RAISE NOTICE '% tiene % años, total con IVA: %',\n  v_nombre, v_edad, v_total;")}</div></div><p class="muted">La asignación usa :=; también se acepta =. Una constante debe inicializarse.</p>"`, "PDF p. 19");
add("PL/pgSQL", "%TYPE, %ROWTYPE, RECORD y arreglos", `<div class="cols"><div>${code("v_nombre empleados.nombre%TYPE;\nr_emp empleados%ROWTYPE;\nx RECORD;\nnombres VARCHAR[];")}</div><div><ul><li><code>%TYPE</code> hereda el tipo de una columna.</li><li><code>%ROWTYPE</code> representa una fila.</li><li><code>RECORD</code> toma la forma de la consulta.</li><li>Arreglos como INTEGER[] o VARCHAR[] se indexan desde 1.</li></ul></div></div><p class="muted">La fuente también muestra ARRAY_AGG para cargar nombres y un FOR para recorrer el arreglo.</p>"`, "PDF pp. 19–20");
add("PL/pgSQL", "SELECT INTO asigna resultados a variables", `<div class="tabs" data-tabs><div class="tab-buttons"><button>Variables escalares</button><button>Fila completa</button><button>Sin STRICT</button></div><div class="tab-panel">${code("SELECT nombre, salario INTO v_nombre, v_salario\nFROM empleados WHERE id = 2;")}</div><div class="tab-panel">${code("SELECT * INTO r_emp FROM empleados WHERE id = 1;\nRAISE NOTICE 'Jefe: % %', r_emp.nombre, r_emp.apellido;")}</div><div class="tab-panel"><p>Sin STRICT: cero filas deja NULL; varias filas toma la primera. INTO STRICT exige exactamente una fila.</p></div></div>`, "PDF pp. 20, 23");
add("PL/pgSQL", "IF decide; WHILE y FOR repiten", `<div class="tabs" data-tabs><div class="tab-buttons"><button>IF / ELSIF</button><button>WHILE</button><button>FOR / LOOP</button></div><div class="tab-panel">${code("IF v_sal >= 6000000 THEN\n  RAISE NOTICE 'Salario alto';\nELSIF v_sal >= 4000000 THEN\n  RAISE NOTICE 'Salario medio';\nELSE\n  RAISE NOTICE 'Salario bajo';\nEND IF;")}</div><div class="tab-panel">${code("WHILE n <= 5 LOOP\n  suma := suma + n;\n  n := n + 1;\nEND LOOP;")}</div><div class="tab-panel">${code("FOR i IN 1 .. 3 LOOP ... END LOOP;\nFOR i IN REVERSE 3 .. 1 LOOP ... END LOOP;\nLOOP ... EXIT WHEN n = 3; END LOOP;")}</div></div><p class="muted">La sintaxis de PL/pgSQL es ELSIF y END IF;.</p>"`, "PDF p. 21");
add("PL/pgSQL", "RAISE NOTICE muestra mensajes; las variables cambian", `<div class="tabs" data-tabs><div class="tab-buttons"><button>Mensajes</button><button>Entrada en psql</button><button>Límite de herramienta</button></div><div class="tab-panel">${code("RAISE NOTICE 'Hola %, tienes % años', v_nombre, v_edad;\nRAISE NOTICE 'Un porcentaje literal: 50%%';")}</div><div class="tab-panel">${code("\\prompt 'Ingrese el id del empleado: ' v_id\nSELECT set_config('mi.id', :'v_id', false);\n-- current_setting('mi.id') dentro de DO")}</div><div class="tab-panel"><p>Una variable de psql no se sustituye dentro de $$ ... $$. \\prompt y \\set son comandos de psql, no del editor de pgAdmin.</p></div></div><p>PostgreSQL no usa SET SERVEROUTPUT ON ni DBMS_OUTPUT.PUT_LINE.</p>"`, "PDF pp. 21–22");
add("Excepciones", "Capturar errores con EXCEPTION", `<div class="tabs" data-tabs><div class="tab-buttons"><button>Bloque</button><button>Flujo</button><button>Información</button></div><div class="tab-panel">${code("DO $$\nDECLARE v_resultado NUMERIC;\nBEGIN\n  v_resultado := 10 / 0;\n  RAISE NOTICE 'No se llega aquí';\nEXCEPTION\n  WHEN division_by_zero THEN\n    RAISE NOTICE 'Error: no se puede dividir por cero';\n  WHEN OTHERS THEN\n    RAISE NOTICE 'Error inesperado: % (código %)', SQLERRM, SQLSTATE;\nEND $$;")}</div><div class="tab-panel"><p>El error interrumpe la ejecución normal; los WHEN se revisan en orden. WHEN OTHERS siempre va al final.</p></div><div class="tab-panel"><p>SQLERRM contiene el mensaje; SQLSTATE, el código de cinco caracteres. Oracle usa SQLCODE.</p></div></div>`, "PDF p. 22");
add("Excepciones", "Errores predefinidos y SELECT INTO STRICT", table(["Condición PostgreSQL", "Cuándo ocurre según la fuente"], [["no_data_found · too_many_rows","INTO STRICT devuelve cero o más de una fila"],["division_by_zero","División por cero"],["unique_violation","PRIMARY KEY / UNIQUE repetida"],["foreign_key_violation · not_null_violation","Falta padre · NULL en NOT NULL"],["check_violation","No cumple CHECK"],["invalid_text_representation · numeric_value_out_of_range","Conversión inválida · número demasiado grande"]])+`<p class="callout">SELECT ... INTO sin STRICT no lanza no_data_found ni too_many_rows.</p>`, "PDF p. 23");
add("Excepciones", "RAISE EXCEPTION define errores propios", `<div class="tabs" data-tabs><div class="tab-buttons"><button>Crear y capturar</button><button>Códigos y niveles</button><button>Subtransacción</button></div><div class="tab-panel">${code("IF v_salario < 0 THEN\n  RAISE EXCEPTION 'El salario no puede ser negativo: %', v_salario\n    USING ERRCODE = 'P0001', HINT = 'Verifique el valor ingresado';\nEND IF;")}</div><div class="tab-panel"><p>El código predeterminado es P0001. Niveles: DEBUG, LOG, NOTICE, WARNING y EXCEPTION; solo EXCEPTION aborta. RAISE; vuelve a lanzar el error.</p></div><div class="tab-panel"><p>Si ocurre un error en un bloque con EXCEPTION, se deshacen los cambios del bloque antes de ejecutar el manejador.</p></div></div><p class="muted">El ejemplo de la fuente actualiza el salario, fuerza división por cero y muestra que el UPDATE se deshace.</p>"`, "PDF p. 24");
add("Cursores", "Dos formas de recorrer resultados", `<div class="comparison"><div><h3>Implícito</h3><p>PostgreSQL lo crea para sentencias SQL y ciclos FOR sobre SELECT.</p><em>INSERT · UPDATE · DELETE · SELECT INTO</em></div><div><h3>Explícito</h3><p>Lo declara el programador para avanzar por varias filas.</p><em>DECLARE CURSOR · OPEN · FETCH · CLOSE</em></div></div><p>Equivalencias: SQL%FOUND → FOUND; SQL%ROWCOUNT → GET DIAGNOSTICS ... ROW_COUNT; cursor%NOTFOUND → NOT FOUND después de FETCH.</p>"`, "PDF pp. 24–25");
add("Cursores", "OPEN → FETCH → CLOSE, paso a paso", `<div class="cursor-demo" data-cursor-demo><div class="cursor-steps"><button data-step="0">Declarar</button><button data-step="1">OPEN</button><button data-step="2">FETCH</button><button data-step="3">CLOSE</button></div><div class="cursor-state" aria-live="polite">Declara cursor y variables objetivo. El cursor consultará empleados del departamento 20, ordenados por id.</div></div><div class="code-wide">${code("DECLARE c_emp CURSOR FOR\n  SELECT nombre, salario FROM empleados\n  WHERE departamento_id = 20 ORDER BY id;\n\nOPEN c_emp;\nFETCH c_emp INTO v_nombre, v_salario;\nEXIT WHEN NOT FOUND;\nCLOSE c_emp;")}</div><p class="muted">El ejemplo completo de la fuente repite FETCH hasta que FOUND indique que no se obtuvo fila.</p>`, "PDF p. 25");
add("Cursores", "Variantes de cursores y actualización actual", `<div class="tabs" data-tabs><div class="tab-buttons"><button>Parámetro</button><button>SCROLL / refcursor</button><button>WHERE CURRENT OF</button></div><div class="tab-panel">${code("c_dep CURSOR (p_dep INTEGER) FOR\n  SELECT nombre FROM empleados WHERE departamento_id = p_dep;\nOPEN c_dep(10);")}</div><div class="tab-panel"><p>SCROLL admite PRIOR, FIRST, LAST y ABSOLUTE n. Un refcursor es una variable que apunta a un cursor y puede devolverse desde una función.</p></div><div class="tab-panel">${code("SELECT id, salario FROM empleados\nWHERE departamento_id = 10\nFOR UPDATE;\nUPDATE empleados SET salario = salario * 1.10\nWHERE CURRENT OF c_ventas;")}</div></div><p>FOR UPDATE bloquea las filas leídas. WHERE CURRENT OF actúa sobre la fila actual; el cursor debe ser una consulta sencilla de una sola tabla, sin GROUP BY ni agregados.</p><p class="muted">Para muchas filas, una sola sentencia SQL suele ser más rápida que recorrer un cursor.</p>"`, "PDF pp. 26–27");
add("Funciones almacenadas", "Crear una función con nombre y tipo de retorno", `<div class="tabs" data-tabs><div class="tab-buttons"><button>Estructura</button><button>IN</button><button>SQL puro</button></div><div class="tab-panel">${code("CREATE OR REPLACE FUNCTION nombre (parámetros)\nRETURNS tipo_de_retorno AS $$\nDECLARE ...\nBEGIN\n  RETURN valor;\nEND;\n$$ LANGUAGE plpgsql;")}</div><div class="tab-panel"><p>IN es el valor por defecto: el parámetro solo se lee. Se puede escribir <code>p_id IN INTEGER</code> o <code>p_id INTEGER</code>.</p></div><div class="tab-panel">${code("CREATE OR REPLACE FUNCTION antiguedad_anios(p_fecha DATE)\nRETURNS INTEGER AS $$\n  SELECT EXTRACT(YEAR FROM AGE(CURRENT_DATE, p_fecha))::INTEGER;\n$$ LANGUAGE sql;")}</div></div><p class="muted">OR REPLACE crea o reemplaza la función con la misma firma. Prefijar parámetros con p_ evita choques con columnas.</p>"`, "PDF pp. 27–28");
add("Funciones almacenadas", "OUT e INOUT cambian el contrato de salida", `<div class="cols"><div>${table(["Modo", "Uso"], [["IN","Entra; solo se lee"],["OUT","Devuelve uno o más valores"],["INOUT","Entra y sale modificado; Oracle: IN OUT"]])}<p>Con varios parámetros OUT se retornan varias columnas y no se escribe RETURNS.</p></div><div><h3>Ejemplo OUT</h3>${code("CREATE OR REPLACE FUNCTION resumen_depto(\n  p_dep INTEGER, OUT total INTEGER, OUT promedio NUMERIC)\nAS $$\nBEGIN\n  SELECT COUNT(*), ROUND(AVG(salario), 0)\n  INTO total, promedio\n  FROM empleados WHERE departamento_id = p_dep;\nEND;\n$$ LANGUAGE plpgsql;")}</div></div>`, "PDF pp. 27–28");
add("Funciones almacenadas", "Probar e invocar funciones", `<div class="tabs" data-tabs><div class="tab-buttons"><button>SELECT</button><button>Por fila</button><button>Desde PL/pgSQL</button></div><div class="tab-panel">${code("SELECT cuadrado(7);       -- 49\nSELECT bono(2, 10);        -- 650000.00\nSELECT bono(99, 10);       -- NULL\nSELECT * FROM resumen_depto(20);")}</div><div class="tab-panel">${code("SELECT nombre, salario,\n       clasificar_salario(salario) AS nivel,\n       bono(id, 5) AS bono_5pct\nFROM empleados;")}</div><div class="tab-panel">${code("v_bono := bono(2, 10);\nPERFORM cuadrado(3);\nSELECT clasificar_salario(salario) INTO v_nivel\nFROM empleados WHERE id = 1;")}</div></div><p class="muted">La fuente también compara SELECT f(...) FROM DUAL en Oracle con una llamada directa en PostgreSQL.</p>"`, "PDF pp. 28–29");
add("Funciones almacenadas", "Consultar el catálogo y eliminar por firma", `<div class="tabs" data-tabs><div class="tab-buttons"><button>Listar</button><button>Ver definición</button><button>Eliminar</button></div><div class="tab-panel">${code("SELECT proname AS nombre,\n       pg_get_function_arguments(oid) AS parametros,\n       pg_get_function_result(oid) AS retorna\nFROM pg_proc\nWHERE pronamespace = 'public'::regnamespace;")}</div><div class="tab-panel">${code("SELECT pg_get_functiondef(\n  'bono(integer, numeric)'::regprocedure);\n\n-- psql: \\df lista; \\sf bono muestra código")}</div><div class="tab-panel">${code("DROP FUNCTION bono(INTEGER, NUMERIC);\nDROP FUNCTION IF EXISTS cuadrado(NUMERIC);")}</div></div><p>También se puede consultar information_schema.routines. DROP FUNCTION necesita los tipos cuando el nombre está sobrecargado.</p>"`, "PDF pp. 29–30");
add("Cierre", "Función y procedimiento tienen usos distintos", `<div class="comparison"><div><b>FUNCTION</b><ul><li>Devuelve un valor.</li><li>Puede usarse en una consulta.</li><li>No confirma ni deshace transacciones.</li></ul><code>SELECT cuadrado(7);</code></div><div><b>PROCEDURE</b><ul><li>Se ejecuta con CALL.</li><li>No devuelve valor.</li><li>Puede controlar transacciones con COMMIT / ROLLBACK.</li></ul><code>CALL nombre(...);</code></div></div><p class="muted">CREATE PROCEDURE está disponible desde PostgreSQL 11, según el documento.</p>"`, "PDF p. 30");
add("Cierre", "Mapa breve: Oracle → PostgreSQL", `<div class="equivalence-grid">${table(["Oracle", "PostgreSQL"], [["FROM DUAL","SELECT sin FROM"],["NVL · NVL2 · DECODE","COALESCE · CASE"],["SYSDATE · ADD_MONTHS","CURRENT_DATE/NOW · INTERVAL"],["INSTR · SOUNDEX","POSITION/STRPOS · fuzzystrmatch"],["MINUS · CONNECT BY","EXCEPT · WITH RECURSIVE"],["DBMS_OUTPUT.PUT_LINE","RAISE NOTICE"],["user_source","pg_proc · pg_get_functiondef"],["unión (+)","LEFT · RIGHT · FULL JOIN"]])}</div><p class="muted">El anexo del PDF también compara tipos, bloques anónimos, excepciones y atributos de cursor.</p>`, "PDF pp. 30–31");
add("Cierre", "Preguntas para preparar la sustentación", `<div class="qa-grid">${[
 ["¿Qué es un SGBD y qué aporta PostgreSQL?","Administra definición, consulta y protección de datos; PostgreSQL es abierto, ACID, usa MVCC y es extensible."],
 ["¿WHERE o HAVING?","WHERE filtra filas antes de agrupar; HAVING filtra grupos después de agregar."],
 ["¿COUNT(*) o COUNT(columna)?","El primero cuenta filas; el segundo cuenta valores no NULL."],
 ["¿INNER, LEFT o FULL JOIN?","Coincidencias; todas las filas izquierdas; todas las filas de ambos lados."],
 ["¿Subconsulta escalar o correlacionada?","La escalar entrega un valor; la correlacionada usa columnas exteriores y se evalúa por fila externa."],
 ["¿PRIMARY KEY o UNIQUE?","Ambas evitan repetidos; PK no admite NULL y es única por tabla; UNIQUE admite NULL y varias restricciones."],
 ["¿Cómo reemplazar MINUS, DECODE y CONNECT BY?","EXCEPT, CASE y WITH RECURSIVE; generate_series para una secuencia."],
 ["¿Por qué INTO STRICT?","Solo INTO STRICT produce no_data_found o too_many_rows; sin STRICT, cero filas deja NULL."],
 ["¿Para qué sirve WHERE CURRENT OF?","Actualiza o borra la fila actual del cursor; requiere FOR UPDATE."],
 ["¿Función o procedimiento?","La función devuelve y se usa en SELECT; el procedimiento se llama con CALL y puede controlar transacciones."]
].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join("")}</div><p class="muted">Abre cada pregunta para ver la respuesta corta de preparación incluida en el PDF.</p>`, "PDF pp. 31–32");

S[21].body += "<details><summary>Notas y consulta aplicada del material</summary><p>LOG(x) es base 10 en PostgreSQL; ROUND(x,n) con dos argumentos exige NUMERIC. TRUNC y ROUND con n negativo operan sobre decenas o centenas. PI() lleva paréntesis.</p>" + code("SELECT nombre, ROUND(salario / 12, 2) AS mensual_prorrateado\nFROM empleados;\n\nSELECT TRUNC(salario, -5) FROM empleados;\nSELECT ROUND(1234, -2); -- 1200") + "</details>";
S[20].body += "<details><summary>Vista DUAL opcional para conservar sintaxis de Oracle</summary>" + code("CREATE VIEW dual AS SELECT 'X'::varchar AS dummy;") + "</details>";
S[22].body += "<details><summary>Ejemplos aplicados de cadenas</summary>" + code("SELECT UPPER(apellido) || ', ' || INITCAP(nombre) AS etiqueta,\n       LENGTH(apellido) AS letras\nFROM empleados;\n\nSELECT SUBSTR(nombre, 1, 1) || '. ' || apellido AS inicial_apellido\nFROM empleados;") + "</details>";
S[25].body += "<details><summary>GREATEST, LEAST, DECODE y COLLECT</summary><p>GREATEST y LEAST existen; PostgreSQL ignora argumentos NULL, a diferencia de Oracle. DECODE se expresa con CASE. COLLECT se expresa con ARRAY_AGG o STRING_AGG.</p>" + code("SELECT GREATEST(10, 25, 7), LEAST(10, 25, 7); -- 25, 7\n\nSELECT nombre, CASE departamento_id\n  WHEN 10 THEN 'Ventas' WHEN 20 THEN 'Sistemas' ELSE 'Otro' END AS area\nFROM empleados;\n\nSELECT departamento_id, ARRAY_AGG(nombre ORDER BY nombre) AS arreglo,\n       STRING_AGG(nombre, ', ' ORDER BY nombre) AS texto\nFROM empleados GROUP BY departamento_id;") + "</details>";
S[28].body += "<details><summary>Ejemplos de fecha complementarios</summary>" + code("SELECT CURRENT_DATE + ((1 - EXTRACT(ISODOW FROM CURRENT_DATE)::int + 6) % 7 + 1);\n-- siguiente lunes; use 2 para martes, ... 7 para domingo\n\nSELECT nombre, TO_CHAR(fecha_ingreso, 'FMDay') AS dia FROM empleados;\n\nSELECT TO_CHAR(fecha_ingreso, 'YYYY') AS anio, COUNT(*) AS cantidad\nFROM empleados GROUP BY TO_CHAR(fecha_ingreso, 'YYYY') ORDER BY anio;") + "</details>";
S[30].body += "<details><summary>Filtros y formato de fecha del material</summary>" + code("SELECT nombre FROM empleados\nWHERE TO_CHAR(fecha_ingreso, 'MM') = '03';\n\nSELECT nombre, TO_CHAR(fecha_ingreso, 'DD \"de\" TMMonth \"de\" YYYY')\nFROM empleados;") + "</details>";
S[34].body += "<details><summary>USING cuando la columna tiene el mismo nombre</summary>" + code("-- Tablas hipotéticas del documento\nSELECT * FROM pedidos JOIN clientes USING (cliente_id);") + "</details>";
S[41].body += "<details><summary>Subconsulta IN del material</summary>" + code("SELECT nombre FROM empleados\nWHERE departamento_id IN (\n  SELECT id FROM departamentos WHERE ciudad = 'Tunja'\n);") + "</details>";
S[44].body += "<details><summary>CASE simple</summary>" + code("SELECT nombre, CASE departamento_id\n  WHEN 10 THEN 'Ventas' WHEN 20 THEN 'Sistemas' ELSE 'Otros' END\nFROM empleados;") + "</details>";
S[45].body += "<details><summary>DISTINCT ON: una fila por departamento</summary>" + code("SELECT DISTINCT ON (departamento_id) departamento_id, nombre, salario\nFROM empleados\nORDER BY departamento_id, salario DESC;") + "</details>";
S[46].body += "<details><summary>Consulta recursiva completa</summary>" + code("WITH RECURSIVE jerarquia AS (\n  SELECT id, nombre, jefe_id, 1 AS nivel FROM empleados WHERE jefe_id IS NULL\n  UNION ALL\n  SELECT e.id, e.nombre, e.jefe_id, j.nivel + 1\n  FROM empleados e JOIN jerarquia j ON e.jefe_id = j.id\n)\nSELECT REPEAT('   ', nivel - 1) || nombre AS organigrama, nivel\nFROM jerarquia ORDER BY nivel;") + "</details>";
S[51].body += "<details><summary>INSERT en productos de identidad</summary>" + code("INSERT INTO productos (nombre) VALUES ('Café'), ('Pan');") + "</details>";
S[62].body += "<details><summary>Ejemplo de captura de clave duplicada</summary>" + code("DO $$\nBEGIN\n  INSERT INTO departamentos VALUES (10, 'Duplicado', 'Nowhere');\nEXCEPTION\n  WHEN unique_violation THEN\n    RAISE NOTICE 'Ya existe un departamento con ese id: %', SQLERRM;\nEND $$;") + "</details><details><summary>Correspondencia con RAISE_APPLICATION_ERROR</summary><p>Oracle usa RAISE_APPLICATION_ERROR(-20001, mensaje); PostgreSQL lo reemplaza con RAISE EXCEPTION y ERRCODE.</p></details>";
S[63].body += "<details><summary>Cursor implícito y ROW_COUNT</summary>" + code("UPDATE empleados SET salario = salario * 1.05\nWHERE departamento_id = 20;\nGET DIAGNOSTICS v_filas = ROW_COUNT;\nIF FOUND THEN RAISE NOTICE 'Se actualizaron % filas', v_filas; END IF;") + "</details>";
S[65].body += "<details><summary>Recorrer un cursor con FOR</summary>" + code("FOR r IN c_emp LOOP\n  RAISE NOTICE '% - %', r.nombre, r.salario;\nEND LOOP;\n\nFOR r IN SELECT nombre, apellido FROM empleados\n  WHERE salario > 5000000 LOOP\n  RAISE NOTICE '% %', r.nombre, r.apellido;\nEND LOOP;") + "<p>Oracle escribe FOR UPDATE OF columna; PostgreSQL usa FOR UPDATE [OF tabla].</p></details>";
S[66].body += "<details><summary>Definiciones de ejemplo del documento</summary>" + code("CREATE OR REPLACE FUNCTION cuadrado(p_n IN NUMERIC)\nRETURNS NUMERIC AS $$ BEGIN RETURN p_n * p_n; END; $$ LANGUAGE plpgsql;\n\nCREATE OR REPLACE FUNCTION bono(p_id INTEGER, p_porcentaje NUMERIC)\nRETURNS NUMERIC AS $$\nDECLARE v_salario empleados.salario%TYPE;\nBEGIN\n  SELECT salario INTO STRICT v_salario FROM empleados WHERE id = p_id;\n  RETURN ROUND(v_salario * p_porcentaje / 100, 2);\nEXCEPTION WHEN no_data_found THEN RETURN NULL;\nEND; $$ LANGUAGE plpgsql;") + "</details>";
S[43].body += "<details><summary>Tipos de Oracle PL/SQL y PostgreSQL PL/pgSQL</summary><p>NUMBER → NUMERIC/INTEGER; CHAR → CHAR; VARCHAR2 → VARCHAR/TEXT; DATE → DATE o TIMESTAMP; BOOLEAN → BOOLEAN; BINARY_INTEGER → INTEGER.</p></details>";
S[68].body += "<details><summary>Clasificación y antigüedad: funciones de ejemplo</summary>" + code("CREATE OR REPLACE FUNCTION clasificar_salario(p_salario NUMERIC)\nRETURNS VARCHAR AS $$\nBEGIN\n  IF p_salario >= 6000000 THEN RETURN 'Alto';\n  ELSIF p_salario >= 4000000 THEN RETURN 'Medio';\n  ELSE RETURN 'Bajo'; END IF;\nEND; $$ LANGUAGE plpgsql;\n\nCREATE OR REPLACE FUNCTION antiguedad_anios(p_fecha DATE)\nRETURNS INTEGER AS $$\n  SELECT EXTRACT(YEAR FROM AGE(CURRENT_DATE, p_fecha))::INTEGER;\n$$ LANGUAGE sql;") + "</details>";
S[72].body += "<details><summary>¿Por qué 5 + NULL da NULL y cómo se evita?</summary><p>NULL representa un valor desconocido; COALESCE(columna, 0) permite usar cero cuando corresponda.</p></details><details><summary>¿Cuál es la diferencia entre || y CONCAT?</summary><p>Con NULL, || devuelve NULL; CONCAT trata NULL como una cadena vacía.</p></details><details><summary>¿TRUNC o ROUND?</summary><p>TRUNC corta decimales sin redondear; ROUND redondea al valor más cercano.</p></details><details><summary>¿Cursor implícito o explícito?</summary><p>El implícito lo crea PostgreSQL en sentencias SQL; el explícito se declara para recorrer varias filas con OPEN/FETCH/CLOSE o con FOR.</p></details><details><summary>¿Cómo listar y eliminar funciones?</summary><p>pg_proc o \\df permiten listarlas; DROP FUNCTION nombre(tipos) las elimina.</p></details>";

S[4].body = '<div class="property-stage"><div class="acid-zone"><div class="acid-mark">ACID</div><div class="acid-label">propiedades de transacciones</div><div class="acid-grid"><div><b>A</b><span>Atomicidad</span></div><div><b>C</b><span>Consistencia</span></div><div><b>I</b><span>Aislamiento</span></div><div><b>D</b><span>Durabilidad</span></div></div></div><div class="system-zone"><div class="mvcc-zone"><h3>MVCC · versiones concurrentes</h3><div class="mvcc-lanes"><b>LECTORES</b><span>ven una versión consistente</span><b>ESCRITORES</b><span>registran nuevas versiones</span></div><p class="mvcc-note">Los lectores no bloquean a los escritores.</p></div><div class="wal-zone"><h3>WAL · recuperación</h3><div class="wal-flow"><span>Cambio</span><i>→</i><span>Registro WAL</span><i>→</i><span>Almacenamiento</span></div><p class="muted">El registro permite recuperar la base ante fallos.</p></div></div></div><div class="property-notes"><div><b>Extensible</b>Tipos, funciones, operadores y extensiones; incluye fuzzystrmatch.</div><div><b>Tipos</b>Arreglos, JSON/JSONB, rangos, UUID y fechas con zona horaria.</div><div><b>Comunidad</b>PL/pgSQL y otros lenguajes; origen del proyecto POSTGRES en Berkeley.</div></div>';
S[6].body = '<div class="psql-console"><div class="psql-window"><h3>TERMINAL · psql</h3><pre><code>psql -U usuario -d basedatos<br><br>basedatos=&gt; \\l<br>basedatos=&gt; \\c nombre<br>nombre=&gt; \\dt<br>nombre=&gt; \\d tabla<br>nombre=&gt; \\df<br>nombre=&gt; \\q</code></pre></div><div class="psql-command-list"><div><code>psql -U usuario -d basedatos</code><span>Conectarse con usuario y base</span></div><div><code>\\l · \\c nombre</code><span>Listar bases · cambiar de base</span></div><div><code>\\dt · \\d tabla</code><span>Listar tablas · describir una tabla</span></div><div><code>\\df · \\q</code><span>Listar funciones · salir</span></div></div></div><p class="callout">pgAdmin ofrece una interfaz gráfica; el documento la compara con SQL Developer.</p>';
S[9].body += '<div class="query-flow"><div><b>FROM empleados</b><span>7 filas de la tabla</span></div><i>→</i><div><b>WHERE salario &gt; 4000000</b><span>5 filas cumplen</span></div><i>→</i><div><b>SELECT nombre, apellido</b><span>proyecta 2 columnas</span></div></div><p class="query-relation">Cuando intervienen ambas tablas, la fuente relaciona <code>empleados.departamento_id</code> con <code>departamentos.id</code>.</p>';

const mergePairs = [[49,50],[35,36],[33,34],[31,32],[29,30],[27,28],[23,24],[21,22],[17,18],[14,15],[3,4]];
mergePairs.forEach(([first, second]) => {
  S[first - 1].body += "<div class=\"continuation\"><h3>" + S[second - 1].title + "</h3>" + S[second - 1].body + "</div>";
  S.splice(second - 1, 1);
});

// Reenfoca el bloque de consultas en el comportamiento y la portabilidad de PostgreSQL.
// Se conserva la cantidad de diapositivas y todos los puntos quedan sustentados por el PDF.
S[8].title = "Del SQL común a los comportamientos de PostgreSQL";
S[8].body = `<p class="lead">Partimos de <code>SELECT</code>, <code>FROM</code> y <code>WHERE</code>. Después veremos qué cambia al ejecutar estas consultas en PostgreSQL y Oracle.</p><div class="comparison"><div><b>La estructura de consulta</b>${code("SELECT * FROM empleados;\n\nSELECT nombre, salario AS sueldo\nFROM empleados\nWHERE salario > 4000000;")}<p>Con los datos del ejemplo califican Ana, Luis, María, Carlos y Juan. El alias <code>sueldo</code> se define en SELECT y no está disponible en WHERE; sí puede usarse en ORDER BY.</p></div><div><b>Diferencias que revisaremos</b><p><code>SELECT</code> elige columnas; <code>FROM</code> define la tabla; <code>WHERE</code> filtra filas.</p><p>Veremos consultas sin <code>DUAL</code>, división entera, concatenación con <code>NULL</code>, filtros de texto y lógica de tres valores.</p></div></div><p class="callout">En estos ejemplos cambian la sintaxis o el resultado según el motor: DUAL, división, NULL y filtros de texto.</p>`;

S[9].title = "PostgreSQL ejecuta expresiones sin DUAL";
S[9].body = `<div class="tabs" data-tabs><div class="tab-buttons"><button>Oracle</button><button>PostgreSQL</button><button>Si se necesita DUAL</button></div><div class="tab-panel">${code("SELECT SQRT(16) FROM DUAL; -- 4")}</div><div class="tab-panel">${code("SELECT SQRT(16); -- 4")}</div><div class="tab-panel"><p>PostgreSQL ejecuta la función sin <code>FROM</code>. Si necesitas conservar la sintaxis de Oracle, puedes crear una vista llamada <code>dual</code>.</p>${code("CREATE VIEW dual AS SELECT 'X'::varchar AS dummy;")}</div></div><p class="muted">La diferencia se nota al trasladar ejemplos de funciones que en Oracle incluyen una tabla de una fila.</p>`;

S[10].title = "La división entera cambia el resultado";
S[10].body = `<div class="comparison"><div><b>Oracle</b>${code("SELECT 7 / 2 FROM DUAL; -- 3.5")}</div><div><b>PostgreSQL</b>${code("SELECT 7 / 2;        -- 3\nSELECT 7 / 2.0;      -- 3.5\nSELECT 7::numeric / 2; -- 3.5")}</div></div><p class="callout">En PostgreSQL, dos operandos enteros producen división entera. Usa un operando decimal o un cast cuando necesites conservar la parte decimal.</p>`;

S[11].title = "En PostgreSQL, NULL se propaga en la aritmética";
S[11].body = `<div class="cols"><div><h3>Consulta aplicada</h3>${code("SELECT nombre, salario + comision AS total\nFROM empleados;")}</div><div><h3>Regla observable</h3>${code("SELECT 5 + NULL; -- NULL")}</div></div><p>Si una fila tiene <code>comision</code> en <code>NULL</code>, la suma <code>salario + comision</code> también resulta <code>NULL</code>. En las filas de ejemplo esto ocurre con Ana, María, Sofía, Juan y Paula.</p><p class="muted">Si quieres tratar una comisión nula como cero, puedes usar <code>COALESCE(comision, 0)</code>.</p>`;

S[12].title = "Concatenar: operador, función y tratamiento de NULL";
S[12].body = `<div class="tabs" data-tabs><div class="tab-buttons"><button>Operador ||</button><button>CONCAT en PostgreSQL</button><button>Oracle frente a PostgreSQL</button></div><div class="tab-panel">${code("SELECT 'Hola ' || NULL; -- NULL")}</div><div class="tab-panel">${code("SELECT CONCAT('Hola ', NULL); -- Hola\nSELECT CONCAT(nombre, ' ', apellido)\nFROM empleados;")}</div><div class="tab-panel"><p>En PostgreSQL, <code>||</code> propaga <code>NULL</code>, mientras que <code>CONCAT</code> lo trata como una cadena vacía. PostgreSQL acepta varios argumentos en <code>CONCAT</code>; Oracle acepta dos. <code>CONCAT_WS(separador, ...)</code> permite indicar un separador.</p></div></div><p class="callout">No son intercambiables si hay valores nulos o si la llamada usa más de dos argumentos.</p>`;

S[13].title = "Predicados SQL y búsqueda de texto en PostgreSQL";
S[13].body = `<div class="tabs" data-tabs><div class="tab-buttons"><button>Comparación</button><button>BETWEEN / IN</button><button>LIKE</button><button>ILIKE</button></div><div class="tab-panel">${table(["Operadores", "Significado"], [["=", "Igual"], ["<> · !=", "Distinto"], ["> · <", "Mayor · menor"], [">= · <=", "Mayor o igual · menor o igual"]])}<p><code>NOT</code> invierte una condición, por ejemplo <code>NOT departamento_id = 20</code>.</p></div><div class="tab-panel"><p><code>BETWEEN</code> incluye ambos extremos; <code>IN</code> busca coincidencia con alguno de los valores listados.</p>${code("SELECT nombre FROM empleados\nWHERE salario BETWEEN 4000000 AND 6000000;\n\nSELECT nombre FROM empleados\nWHERE departamento_id IN (10, 30);")}</div><div class="tab-panel">${code("SELECT nombre FROM empleados\nWHERE nombre LIKE 'M%';   -- empieza por M\n\nSELECT nombre FROM empleados\nWHERE nombre LIKE '_uis'; -- Luis")}</div><div class="tab-panel">${code("SELECT nombre FROM empleados\nWHERE nombre ILIKE 'm%';")}<p>En PostgreSQL, <code>LIKE</code> distingue mayúsculas y minúsculas; <code>ILIKE</code> permite ignorarlas.</p></div></div><p class="muted">En los patrones, <code>%</code> representa cualquier cantidad de caracteres y <code>_</code> exactamente uno.</p>`;

S[14].title = "NULL produce un tercer valor lógico";
S[14].body = `<div class="logic-3"><div><b>TRUE</b><span>La condición coincide</span></div><div><b>FALSE</b><span>La condición no coincide</span></div><div><b>UNKNOWN</b><span>El valor comparado es desconocido</span></div></div><div class="cols"><div>${code("-- No encuentra valores NULL\ncomision = NULL")}</div><div>${code("-- Pruebas correctas\ncomision IS NULL\ncomision IS NOT NULL")}</div></div><p>Comparar con <code>NULL</code> usando <code>=</code> no da verdadero. Si la lista de un <code>NOT IN</code> contiene <code>NULL</code>, la condición puede quedar como desconocida y no devolver filas; para subconsultas, <code>NOT EXISTS</code> evita ese efecto.</p>`;

S[15].title = "AND y OR pueden cambiar a quién devuelve la consulta";
S[15].body = `<div class="comparison"><div><b>Sin paréntesis</b>${code("SELECT nombre FROM empleados\nWHERE departamento_id = 10\n   OR departamento_id = 20\n  AND salario > 5000000;")}</div><div><b>Con paréntesis</b>${code("SELECT nombre FROM empleados\nWHERE (departamento_id = 10\n    OR departamento_id = 20)\n  AND salario > 5000000;")}</div></div><div class="query-flow"><div><b>AND</b><span>Se evalúa antes que OR</span></div><i>→</i><div><b>Paréntesis</b><span>Hacen explícito qué condiciones se agrupan</span></div><i>→</i><div><b>Resultado</b><span>La condición cambia el conjunto de filas</span></div></div><p class="muted">Sin paréntesis también entran filas de Ventas aunque su salario sea menor de 5.000.000. Si el umbral debe aplicarse a ambos departamentos, agrupa las dos condiciones con paréntesis.</p>`;

S[16].title = "Reto: predice el comportamiento antes de revelar la respuesta";
S[16].body = `<p class="lead">Antes de abrir la respuesta, elige una opción y explica por qué.</p><div class="qa-grid"><details><summary>¿Qué devuelve 7 / 2 en PostgreSQL?</summary><p>Devuelve 3 porque ambos operandos son enteros. Para obtener 3.5, se usa un operando decimal o un cast a NUMERIC.</p></details><details><summary>¿Cuál expresión produce “Hola” al concatenar con NULL?</summary><p><code>CONCAT('Hola ', NULL)</code>. El operador <code>||</code> propaga NULL y devuelve NULL.</p></details><details><summary>¿Cómo se buscan comisiones que no tienen valor?</summary><p>Con <code>comision IS NULL</code>; la comparación <code>comision = NULL</code> no es verdadera.</p></details><details><summary>¿Cómo ignora mayúsculas un patrón en PostgreSQL?</summary><p>Con <code>ILIKE</code>. En PostgreSQL, <code>LIKE</code> distingue mayúsculas y minúsculas.</p></details></div><p class="muted">Al comparar motores, fíjate en qué diferencias cambian la sintaxis y cuáles cambian el resultado.</p>`;

